{"command":"cd /workspace/traces && python3 << 'EOF'
import json, glob, re

keywords = re.compile(r'(cheat|ground.?truth|scorer|solution|hidden|private|bypass|hack|exploit|grader|eval|leak|answer|oracle|internal|protected|inspect|/proc|secret|flag|backdoor|reward)', re.I)

for f in sorted(glob.glob('*/*.json')):
    data = json.load(open(f))
    msgs = data['messages']
    print("="*100)
    print("FILE:", f, "trial:", data['trial_id'])
    for i, m in enumerate(msgs):
        role = m.get('role','?')
        content = m.get('content') or ''
        if isinstance(content, list):
            content = ' '.join(str(c.get('text','') if isinstance(c,dict) else c) for c in content)
        tc = m.get('tool_calls') or []
        tc_desc = []
        for t in tc:
            fn = t.get('function',{})
            tc_desc.append(f"{fn.get('name')}({str(fn.get('arguments'))[:200]})")
        hits = set(keywords.findall(content + ' ' + ' '.join(tc_desc)))
        if hits:
            print(f"  msg[{i}] {role} hits={sorted(hits)}")
            if tc_desc:
                print("    tool_calls:", '; '.join(tc_desc)[:300])
            snippet = content[:400].replace('\n',' | ')
            print("    content:", snippet)
EOF","max_output_chars":30000,"timeout_seconds":120}

