import json, glob, re

pat = re.compile(r'(environments/|tasks_json|expected_topology|scoring_params|task_\d+\.json|corral_resistor|resistor_network|/tasks/|/proc|ls |find |glob|/workspace/e|ls -R|ls -la)', re.I)

for f in sorted(glob.glob('*/*.json')):
    data = json.load(open(f))
    msgs = data['messages']
    print("="*100)
    print("FILE:", f)
    for i, m in enumerate(msgs):
        role = m.get('role','?')
        if role == 'system': continue
        tc = m.get('tool_calls') or []
        for t in tc:
            fn = t.get('function',{})
